previewCss:
.darma-loader-darma-b17-laser-cut { --accent: var(--loader-color, #334155); --accent-2: var(--loader-secondary-color, #f43f5e); width: var(--loader-size, 118px); height: var(--loader-size, 118px); position: relative; }
.darma-loader-darma-b17-laser-cut .darma-loader-darma-b17-laser-cut__sheet { position: absolute; inset: 6%; border-radius: 4px; background: repeating-linear-gradient(45deg, color-mix(in srgb, #fff 8%, var(--accent)) 0 6px, var(--accent) 0 12px); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 25%, transparent); }
.darma-loader-darma-b17-laser-cut .darma-loader-darma-b17-laser-cut__kerf { position: absolute; left: 22%; top: 22%; width: 56%; height: 56%; border-radius: 6px; border: 3px solid var(--accent-2); box-shadow: 0 0 12px color-mix(in srgb, var(--accent-2) 55%, transparent); animation: darma-loader-darma-b17-laser-cut-laser-kerf calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-laser-cut .darma-loader-darma-b17-laser-cut__head { position: absolute; left: 20%; top: 18%; width: 10%; height: 10%; border-radius: 3px; background: linear-gradient(#e2e8f0, #64748b); animation: darma-loader-darma-b17-laser-cut-laser-path calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-laser-cut .darma-loader-darma-b17-laser-cut__spark { position: absolute; left: 22%; top: 22%; width: 7%; height: 7%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 80%, var(--accent-2)), transparent 70%); animation: darma-loader-darma-b17-laser-cut-laser-flare calc(var(--loader-speed, 1s) * .2) steps(1, end) infinite, darma-loader-darma-b17-laser-cut-laser-path calc(var(--loader-speed, 1s) * 4) linear infinite; }
@keyframes darma-loader-darma-b17-laser-cut-laser-path { 0% { transform: translate(0, 0); } 25% { transform: translate(calc(var(--loader-size, 118px) * .56), 0); } 50% { transform: translate(calc(var(--loader-size, 118px) * .56), calc(var(--loader-size, 118px) * .56)); } 75% { transform: translate(0, calc(var(--loader-size, 118px) * .56)); } 100% { transform: translate(0, 0); } }
@keyframes darma-loader-darma-b17-laser-cut-laser-kerf { 0% { opacity: 0; } 25% { opacity: .3; } 50% { opacity: .58; } 75% { opacity: .82; } 94% { opacity: 1; } 100% { opacity: 0; } }
@keyframes darma-loader-darma-b17-laser-cut-laser-flare { 0%, 49% { opacity: 1; } 50%, 100% { opacity: .35; } }

